program.compute:
options = read('/input/options')
ids = []
for item in options:
    ids = ids + [item['id']]
result = []
for pair in combinations(ids, 2):
    if valid(list(pair)):
        result = list(pair)
        break
if not result:
    for triple in combinations(ids, 3):
        if valid(list(triple)):
            result = list(triple)
            break

program.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
    else:
        result = []
else:
    if valid(result):
        write('/output/selection', result)
if valid(result):
    delivery = receipt('report')
    if delivery == 'success':
        pass
    elif delivery == 'unknown':
        state = status('report')
        if state == 'not_sent':
            send('report', 'team', result)
    elif delivery == 'unattempted' or delivery == 'failure':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

